#include "stdafx.h"#include "Queue.h"#include "..\Lang.h"//#define _MAX_POLY 64//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Структураtypedef struct : public SPROLOZ  {  int nWidth;  COLORREF  lg;// Цвет края  COLORREF  fn;// Цвет центра  COLORREF  dk;// Цвет края  POINT point[_MAX_POLY];  int   nCount;  } Queue_PipeF;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция удаленияvoid ClearPipeF(SQueue& q,void* s)  {  Queue_PipeF* p = (Queue_PipeF*)s;//  ::DeleteObject( p->m_hRgn );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void SetT(RGBTRIPLE& val,COLORREF color);//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintPipeF(DefinePaint)  {  QueueP(Queue_PipeF);  if ( p->fn == p->dk )    {    ASS(0)    }  else  if ( p->lg == p->dk )    {    RGBTRIPLE rgb[2];//0-центр,1-край    SetT( rgb[0], p->fn );//0-центр    SetT( rgb[1], p->dk );//1-край    //        int m = p->nWidth/2;    if ( p->nWidth % 2 ) m++;    int w = p->nWidth;    for ( int n = 0; n <= m; n++ )      {      COLORREF color = Col(rgb[1],rgb[0],(int)n,m);      LOGBRUSH lb = {BS_SOLID,color,0};      HPEN hPen = ::ExtCreatePen(PS_SOLID|PS_ENDCAP_FLAT|PS_GEOMETRIC,w,&lb,0,NULL);      HPEN hOld = (HPEN)::SelectObject( hDC, hPen );      ::Polyline( hDC, p->point, p->nCount );      ::SelectObject( hDC, hOld);      ::DeleteObject( hPen );      w = max(0,w-2);       }    //    }  else    {    ASS(0)    }  return 1;  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~void AddPipeF(DefineTegs)  {  AddQueueEx(Queue_PipeF);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintPipeF;  p->clear = &ClearPipeF;  //  p->nWidth = 5;  //  STegObj obj[] =    {    { 'I', "w"    , &p->nWidth },    { 'I', "width", &p->nWidth },    { 'Z', "poly" ,  p->point , 63 },    { 'Z', "pt"   ,  p->point , 63 },    };  //  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  p->lg = def.lgPipe;// Цвет края  p->fn = def.fnPipe;// Цвет центра  p->dk = def.dkPipe;// Цвет края  //  while ( p->point[p->nCount].x != -10000 ) p->nCount++;  //  ::SetRect( &p->mRect, p->point[0].x-p->nWidth/2, p->point[0].y-p->nWidth/2,                        p->point[0].x+p->nWidth/2, p->point[0].y+p->nWidth/2 );  }//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~